WITH replication = {
	'class' : 'SimpleStrategy',
	'replication_factor' : 3
};

use test_neptunao;

create table if not exists ubuntu (
	id timeuuid PRIMARY KEY,
	precise_pangolin text,
	trusty_tahr text,
	wily_werewolf text,	
	vivid_vervet text,
	saucy_salamander text,
	lucid_lynx text
);
{noformat}

